def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    pq = [(0, s)]

